FILES={'scripts/windows_background.py': '"""Windows startup plumbing only; never run a second polling loop here.\n\nUse pythonw for the scheduled login action. CREATE_NO_WINDOW, unlike SW_HIDE,\nprevents Windows Terminal delegation from allocating a console in the first place.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport os\nfrom pathlib import Path\nimport subprocess\nimport sys\nimport time\n\n\nROOT = Path(__file__).resolve().parents[1]\n\n\ndef no_console_options() -> dict:\n    if os.name != "nt":\n        raise RuntimeError("This launcher requires Windows")\n    return {"creationflags": subprocess.CREATE_NO_WINDOW, "stdin": subprocess.DEVNULL}\n\n\ndef monitor(root: Path = ROOT) -> int:\n    powershell = Path(os.environ["SystemRoot"]) / "System32/WindowsPowerShell/v1.0/powershell.exe"\n    # The GUI launcher stays alive so Task Scheduler still supervises the watcher\n    # and applies its existing restart policy. It does not start the bot itself.\n    log_path = root / "data/logs"\n    log_path.mkdir(parents=True, exist_ok=True)\n    with (log_path / "login-watch.log").open("ab", buffering=0) as log:\n        return subprocess.call(\n            [str(powershell), "-NoProfile", "-NonInteractive", "-ExecutionPolicy",\n             "Bypass", "-File", str(root / "scripts/login-watch.ps1")],\n            cwd=root, stdout=log, stderr=log, **no_console_options(),\n        )\n\n\ndef start_bot(data_path: Path, root: Path = ROOT) -> int:\n    logs = data_path / "logs"\n    logs.mkdir(parents=True, exist_ok=True)\n    # GUI venv launcher also avoids a console in the interpreter subprocess.\n    python = root / ".venv/Scripts/pythonw.exe"\n    with (logs / "console.log").open("ab", buffering=0) as out, \\\n            (logs / "console-error.log").open("ab", buffering=0) as err:\n        child = subprocess.Popen(\n            [str(python), "-m", "team_bot", "run"], cwd=root,\n            stdout=out, stderr=err, **no_console_options(),\n        )\n    # Publish the launcher\'s PID, preserving existing start/stop/watch validation.\n    # If publishing fails, do not leave an untracked new process behind.\n    try:\n        temporary = data_path / f"process.pid.{os.getpid()}.tmp"\n        temporary.write_text(str(child.pid), encoding="ascii")\n        os.replace(temporary, data_path / "process.pid")\n    except BaseException:\n        child.terminate()\n        child.wait(timeout=10)\n        raise\n    time.sleep(3)\n    if child.poll() is not None:\n        raise RuntimeError("启动失败，请查看数据目录 logs/console-error.log。")\n    return child.pid\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("action", choices=("monitor", "start"))\n    parser.add_argument("--data-path", type=Path)\n    args = parser.parse_args()\n    if args.action == "monitor":\n        return monitor()\n    if args.data_path is None:\n        parser.error("start requires --data-path")\n    print(start_bot(args.data_path))\n    return 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'team_bot/process_control.py': None, 'scripts/common.ps1': '\ufeff$ErrorActionPreference = \'Stop\'\n$ProjectRoot = Split-Path $PSScriptRoot -Parent\nSet-Location -LiteralPath $ProjectRoot\n$PythonExe = Join-Path $ProjectRoot \'.venv\\Scripts\\python.exe\'\n$PythonWindowless = Join-Path $ProjectRoot \'.venv\\Scripts\\pythonw.exe\'\n$env:PYTHONUTF8 = \'1\'\nfunction Invoke-WindowlessPython {\n    param([string[]]$PythonArgs)\n    # Windows PowerShell native-command invocation may allocate a console even\n    # when its own parent has none. Explicitly suppress it for startup helpers.\n    $QuotedArgs = foreach ($Argument in $PythonArgs) {\n        if ($Argument.Contains(\'"\')) { throw \'启动参数含无效引号。\' }\n        \'"\' + ($Argument -replace \'(\\\\+)$\', \'$1$1\') + \'"\'\n    }\n    $Info = New-Object System.Diagnostics.ProcessStartInfo\n    # The Windows venv console launcher may create a console for its interpreter\n    # child despite CreateNoWindow on the launcher. Use its GUI counterpart too.\n    $Info.FileName = $PythonWindowless\n    $Info.Arguments = $QuotedArgs -join \' \'\n    $Info.WorkingDirectory = $ProjectRoot\n    $Info.UseShellExecute = $false\n    $Info.CreateNoWindow = $true\n    $Info.RedirectStandardOutput = $true\n    $Info.RedirectStandardError = $true\n    $Info.StandardOutputEncoding = [Text.Encoding]::UTF8\n    $Info.StandardErrorEncoding = [Text.Encoding]::UTF8\n    $Child = New-Object System.Diagnostics.Process\n    $Child.StartInfo = $Info\n    try {\n        [void]$Child.Start()\n        $OutputTask = $Child.StandardOutput.ReadToEndAsync()\n        $ErrorTask = $Child.StandardError.ReadToEndAsync()\n        $Child.WaitForExit()\n        $OutputText = $OutputTask.Result\n        $ErrorText = $ErrorTask.Result\n        $global:LASTEXITCODE = $Child.ExitCode\n        if ($Child.ExitCode -ne 0) { throw "后台启动辅助程序失败（退出码 $($Child.ExitCode)），请检查配置及数据目录日志。" }\n        if ($OutputText) { $OutputText.TrimEnd([char[]]"`r`n") -split \'\\r?\\n\' }\n    } finally { $Child.Dispose() }\n}\nfunction Test-BotProcess {\n    param($Candidate)\n    return ($Candidate -and $Candidate.ExecutablePath -in @($PythonExe, $PythonWindowless) -and $Candidate.CommandLine -like \'*team_bot run*\')\n}\nfunction Invoke-Bot {\n    param([string[]]$BotArgs)\n    if (-not (Test-Path -LiteralPath $PythonExe)) { throw \'请先运行 install.cmd 安装依赖。\' }\n    & $PythonExe -m team_bot @BotArgs\n    if ($LASTEXITCODE -ne 0) { throw "操作失败（退出码 $LASTEXITCODE）。" }\n}\n', 'scripts/start.ps1': '\ufeff. "$PSScriptRoot\\common.ps1"\nif (-not (Test-Path -LiteralPath $PythonExe)) { throw \'请先运行 install.cmd 安装依赖。\' }\n$DataPath = (Invoke-WindowlessPython -PythonArgs @(\'-m\',\'team_bot\',\'paths\') | Select-Object -Last 1)\nif ($LASTEXITCODE -ne 0) { throw \'配置无效，请运行 configure.cmd 核对。\' }\nNew-Item -ItemType Directory -Path $DataPath -Force | Out-Null\nRemove-Item -LiteralPath (Join-Path $DataPath \'autostart.stop\') -ErrorAction SilentlyContinue\n$PidPath = Join-Path $DataPath \'process.pid\'\nif (Test-Path -LiteralPath $PidPath) {\n    $ExistingPid = [int](Get-Content -LiteralPath $PidPath)\n    $ExistingProcess = Get-CimInstance Win32_Process -Filter "ProcessId=$ExistingPid"\n    if (Test-BotProcess $ExistingProcess) { throw \'机器人已经在运行。\' }\n}\n$LogPath = Join-Path $DataPath \'logs\'\nNew-Item -ItemType Directory -Path $LogPath -Force | Out-Null\n$LaunchResult = Invoke-WindowlessPython -PythonArgs @("$PSScriptRoot\\windows_background.py",\'start\',\'--data-path\',$DataPath)\nif ($LASTEXITCODE -ne 0) { throw \'启动失败。请查看数据目录 logs/console-error.log，并运行 diagnose.cmd。\' }\nWrite-Host "机器人已启动，进程编号 $LaunchResult。运行 stop.cmd 停止。"\n', 'scripts/stop.ps1': '\ufeff. "$PSScriptRoot\\common.ps1"\n$DataPath = (Invoke-WindowlessPython -PythonArgs @(\'-m\',\'team_bot\',\'paths\') | Select-Object -Last 1)\nNew-Item -ItemType Directory -Path $DataPath -Force | Out-Null\n\'manual stop\' | Set-Content -LiteralPath (Join-Path $DataPath \'autostart.stop\')\n$PidPath = Join-Path $DataPath \'process.pid\'\nif (-not (Test-Path -LiteralPath $PidPath)) { Write-Host \'未发现运行进程文件。\'; exit 0 }\n$BotPid = [int](Get-Content -LiteralPath $PidPath)\n$BotProcess = Get-CimInstance Win32_Process -Filter "ProcessId=$BotPid"\nif ($BotProcess) {\n    if (-not (Test-BotProcess $BotProcess)) { throw \'此编号属于其他进程，无法停止，请核对。\' }\n    # Windows venv launcher may have a Python interpreter child. Stop only this verified process tree.\n    $AllProcesses = @(Get-CimInstance Win32_Process)\n    $Descendants = @()\n    $Parents = @($BotPid)\n    while ($Parents.Count -gt 0) {\n        $Children = @($AllProcesses | Where-Object { $_.ParentProcessId -in $Parents })\n        if ($Children | Where-Object { $_.Name -notmatch \'^python(w)?\\.exe$\' -and -not ($_.Name -eq \'conhost.exe\' -and $_.ExecutablePath -eq "$env:windir\\system32\\conhost.exe") }) { throw \'机器人存在未知子进程，请人工检查后停止。\' }\n        $Descendants += $Children\n        $Parents = @($Children | ForEach-Object { [int]$_.ProcessId })\n    }\n    [array]::Reverse($Descendants)\n    foreach ($Child in $Descendants) { Stop-Process -Id $Child.ProcessId -ErrorAction SilentlyContinue }\n    # The venv launcher may exit as soon as its interpreter child stops.\n    Stop-Process -Id $BotPid -ErrorAction SilentlyContinue\n}\nRemove-Item -LiteralPath $PidPath -ErrorAction SilentlyContinue\nWrite-Host \'机器人已停止。数据库和待执行任务在重启后恢复。\'\n', 'scripts/login-watch.ps1': '. "$PSScriptRoot\\common.ps1"\n$DataPath = (Invoke-WindowlessPython -PythonArgs @(\'-m\',\'team_bot\',\'paths\') | Select-Object -Last 1)\nif ($LASTEXITCODE -ne 0) { exit 1 }\n$StopPath = Join-Path $DataPath \'autostart.stop\'\n$PidPath = Join-Path $DataPath \'process.pid\'\nRemove-Item -LiteralPath $StopPath -ErrorAction SilentlyContinue\nwhile (-not (Test-Path -LiteralPath $StopPath)) {\n    $Running = $false\n    if (Test-Path -LiteralPath $PidPath) {\n        $SavedBotId = 0\n        if ([int]::TryParse((Get-Content -LiteralPath $PidPath | Select-Object -First 1), [ref]$SavedBotId)) {\n            $Process = Get-CimInstance Win32_Process -Filter "ProcessId=$SavedBotId" -ErrorAction SilentlyContinue\n            $Running = Test-BotProcess $Process\n        }\n    }\n    if (-not $Running) {\n        # Run within this console-free watcher, rather than creating another shell.\n        # A failed recovery must not terminate the 30-second retry loop.\n        try { & "$PSScriptRoot\\start.ps1" *> $null } catch { }\n    }\n    Start-Sleep -Seconds 30\n}\n', 'start.cmd': '@echo off\npowershell.exe -NoProfile -ExecutionPolicy Bypass -File "%~dp0scripts\\start.ps1"\npause\n', 'stop.cmd': '@echo off\npowershell.exe -NoProfile -ExecutionPolicy Bypass -File "%~dp0scripts\\stop.ps1"\npause\n', 'team_bot/maintenance.py': "import sqlite3\nimport zipfile\nimport os\nfrom contextlib import closing\nfrom pathlib import Path\nfrom datetime import timedelta\n\n\nclass InstanceLock:\n    def __init__(self, directory):\n        directory.mkdir(parents=True, exist_ok=True)\n        self.path = directory / 'instance.lock'\n        self.file = None\n\n    def __enter__(self):\n        self.file = self.path.open('a+b')\n        self.file.seek(0)\n        try:\n            if os.name == 'nt':\n                import msvcrt\n                msvcrt.locking(self.file.fileno(), msvcrt.LK_NBLCK, 1)\n            else:\n                import fcntl\n                fcntl.flock(self.file.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)\n        except OSError:\n            self.file.close()\n            raise RuntimeError('已有实例正在运行，请先停止') from None\n        if self.path.stat().st_size == 0:\n            self.file.write(b'0')\n            self.file.flush()\n        return self\n\n    def __exit__(self, *args):\n        if os.name == 'nt':\n            import msvcrt\n            self.file.seek(0)\n            msvcrt.locking(self.file.fileno(), msvcrt.LK_UNLCK, 1)\n        self.file.close()\n\n\ndef backup(service):\n    c = service.c\n    c.backups.mkdir(parents=True, exist_ok=True)\n    name = c.now().strftime('%Y%m%d-%H%M%S-%f')\n    temp = c.backups / (name + '.sqlite3')\n    try:\n        with closing(sqlite3.connect(temp)) as target:\n            service.db.conn.backup(target)\n        dest = c.backups / (name + '.zip')\n        with zipfile.ZipFile(dest, 'w', zipfile.ZIP_DEFLATED) as z:\n            z.write(temp, 'team.sqlite3')\n            for pg_name in ('progress.sqlite3','progress-acceptance.sqlite3'):\n                pg_source=c.data/pg_name\n                if pg_source.exists():\n                    pg_stage=c.backups/(name+'-'+pg_name)\n                    try:\n                        with closing(sqlite3.connect(pg_source)) as source, closing(sqlite3.connect(pg_stage)) as target:source.backup(target)\n                        z.write(pg_stage,pg_name)\n                    finally:pg_stage.unlink(missing_ok=True)\n            for folder in ('materials', 'exports'):\n                for p in (c.data / folder).rglob('*'):\n                    if p.is_file():\n                        z.write(p, p.relative_to(c.data))\n    finally:\n        temp.unlink(missing_ok=True)\n    cutoff = c.now().timestamp() - timedelta(days=c.retention).total_seconds()\n    for p in c.backups.glob('*.zip'):\n        if p.stat().st_mtime < cutoff and p != dest:\n            p.unlink()\n    return dest\n\n\ndef restore(config, archive):\n    from .db import DB\n    config.data.mkdir(parents=True, exist_ok=True)\n    with InstanceLock(config.data):\n        if (config.data / 'team.sqlite3').exists():\n            old = DB(config.data / 'team.sqlite3')\n            from .service import Service\n            try:\n                backup(Service(config, old))\n            finally:\n                old.close()\n        with zipfile.ZipFile(archive) as z:\n            names = z.namelist()\n            if 'team.sqlite3' not in names:\n                raise ValueError('备份缺少数据库')\n            for name in names:\n                path = (config.data / name).resolve()\n                if not path.is_relative_to(config.data.resolve()) or name.startswith(('/', '\\\\')):\n                    raise ValueError('备份含不安全路径')\n                if name not in ('team.sqlite3','progress.sqlite3','progress-acceptance.sqlite3') and not name.startswith(('materials/', 'exports/')):\n                    raise ValueError('备份含非项目数据')\n            # 先验证再替换，避免损坏备份覆盖当前数据库。\n            staged = config.data / 'restore-check.sqlite3'\n            staged.write_bytes(z.read('team.sqlite3'))\n            try:\n                with closing(sqlite3.connect(staged)) as check:\n                    if check.execute('PRAGMA integrity_check').fetchone()[0] != 'ok':\n                        raise ValueError('备份数据库完整性检查失败')\n                for pg_name in ('progress.sqlite3','progress-acceptance.sqlite3'):\n                    if pg_name in names:\n                        checkfile=config.data/('restore-check-'+pg_name);checkfile.write_bytes(z.read(pg_name))\n                        try:\n                            with closing(sqlite3.connect(checkfile)) as check:\n                                if check.execute('PRAGMA integrity_check').fetchone()[0]!='ok':raise ValueError('进度备份完整性检查失败')\n                        finally:checkfile.unlink(missing_ok=True)\n                        for suffix in ('-wal','-shm'):Path(str(config.data/pg_name)+suffix).unlink(missing_ok=True)\n                for suffix in ('-wal', '-shm'):\n                    Path(str(config.data / 'team.sqlite3') + suffix).unlink(missing_ok=True)\n                for name in names:\n                    target = config.data / name\n                    target.parent.mkdir(parents=True, exist_ok=True)\n                    target.write_bytes(z.read(name))\n                # 备份数据库中的资料绝对路径适配恢复位置。\n                db = DB(config.data / 'team.sqlite3')\n                for r in db.all('SELECT id,path FROM documents'):\n                    db.run('UPDATE documents SET path=? WHERE id=?', (str(config.data / 'materials' / Path(r['path']).name), r['id']))\n                db.close()\n            finally:\n                staged.unlink(missing_ok=True)\n    return '恢复完成；发件箱保留原状态，可能需要管理员检查未确认发送记录'\n"}
SHA256={'scripts/windows_background.py': '349dc389468115b85ca6eedd870b9164823fce8281a3a201fb5d824e138dabf0', 'scripts/common.ps1': '450ebea71fc2e20d0f7dcf777367657aed6a8a7ad2a01a4f71e9a2eeb04fb906', 'scripts/start.ps1': '51672fcafeae995da8197d146044c48ba3361f54ded0e33993840ee576cdabb0', 'scripts/stop.ps1': 'b54f856136ab4a07326f525c518062799f48bf1a2f5038a631eecfa70ba50883', 'scripts/login-watch.ps1': '6b822685824b71117be327e4a048153d3a567aa4dcad2b9e86a7fd1d3b90e35f', 'start.cmd': '02f9a7fae4c3e15bb6e5541ec071af6a6b1e03a1f9c3de3f19b44f2751180805', 'stop.cmd': '956c29434b9f323024c21bb6e646c06018d6077fffce23e37f81180e849a7250', 'team_bot/maintenance.py': '52a1f7cdca7f919477bb337177b4ae5556c6fd14dff88136226c97dfe5a4ee69'}
